import { prebuild } from '@mintlify/prebuild';
import { mockProcessExit } from 'vitest-mock-process';
import { configurePreviewPath } from '../constants.js';
import { dev, isNativePackagesEnabled } from '../index.js';
import listener from '../local-preview/listener/index.js';
import { packageRoute, setPackagesRebuiltListener, startPackagesDev, } from '../local-preview/packages/index.js';
const captured = vi.hoisted(() => ({ app: undefined }));
vi.mock('http', async (importOriginal) => {
    const actual = await importOriginal();
    const createServer = (app) => {
        captured.app = app;
        return { listen: vi.fn() };
    };
    return { ...actual, default: { ...actual, createServer }, createServer };
});
vi.mock('socket.io', () => ({
    Server: vi.fn(() => ({ emit: vi.fn(), on: vi.fn() })),
}));
vi.mock('fs-extra', () => {
    const mocks = {
        ensureDir: vi.fn().mockResolvedValue(undefined),
        pathExists: vi.fn().mockResolvedValue(true),
        readFileSync: vi.fn().mockReturnValue('0.0.100'),
        emptyDirSync: vi.fn(),
        outputFileSync: vi.fn(),
    };
    return { ...mocks, default: mocks };
});
vi.mock('@mintlify/prebuild', () => ({
    prebuild: vi.fn().mockResolvedValue(undefined),
    getFileListSync: vi.fn().mockReturnValue([]),
}));
vi.mock('is-online', () => ({ default: vi.fn().mockResolvedValue(true) }));
vi.mock('../local-preview/update.js', () => ({
    silentUpdateClient: vi.fn().mockResolvedValue({ needsUpdate: false, error: undefined }),
}));
vi.mock('../local-preview/preview-lock.js', () => ({
    acquirePreviewLock: vi.fn().mockReturnValue(vi.fn()),
}));
vi.mock('../util.js', () => ({
    maybeFixMissingWindowsEnvVar: vi.fn(),
    seedPreviewFromShared: vi.fn(),
}));
vi.mock('../local-preview/run.js', () => ({ run: vi.fn().mockResolvedValue(undefined) }));
vi.mock('../local-preview/setupNext.js', () => ({
    setupNext: vi.fn(async () => (_req, res) => {
        res.end('next');
    }),
}));
vi.mock('../local-preview/listener/index.js', () => ({
    default: vi.fn(),
    initializeImportCache: vi.fn(),
    initializeFrontmatterHashCache: vi.fn(),
    initializeDocsConfigHashCache: vi.fn(),
}));
vi.mock('../local-preview/listener/referencedFiles.js', () => ({
    refreshTrackedReferencedFiles: vi.fn(),
}));
vi.mock('../local-preview/on-demand-page.js', () => ({
    ensurePageCompiled: vi.fn().mockResolvedValue(undefined),
    getFailedCompileEvents: vi.fn().mockReturnValue([]),
    markOnDemandPagesReady: vi.fn(),
    setCompileListener: vi.fn(),
}));
vi.mock('../local-preview/packages/index.js', () => ({
    startPackagesDev: vi.fn().mockResolvedValue(undefined),
    setPackagesRebuiltListener: vi.fn(),
    packageRoute: {
        prefix: '/_mintlify/pkg',
        handler: vi.fn((_req, res) => res.end('pkg')),
    },
}));
const originalChdir = process.chdir;
const processExitMock = mockProcessExit();
const argv = { _: [], $0: '', packageName: 'mint', cliVersion: '1.0.0' };
const setFlag = (value) => vi.stubEnv('MINTLIFY_NATIVE_NPM_PACKAGES', value);
const startRun = async () => {
    const { run } = await vi.importActual('../local-preview/run.js');
    await run({ ...argv, needsUpdate: false });
};
const get = async (path) => {
    const { createServer } = await vi.importActual('http');
    const server = createServer(captured.app);
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    try {
        const { port } = server.address();
        return await (await fetch(`http://127.0.0.1:${port}${path}`)).text();
    }
    finally {
        await new Promise((resolve) => server.close(resolve));
    }
};
beforeEach(() => {
    vi.clearAllMocks();
    process.chdir = vi.fn();
    captured.app = undefined;
});
afterEach(() => {
    process.chdir = originalChdir;
    vi.unstubAllEnvs();
});
describe('isNativePackagesEnabled', () => {
    it('is on only when MINTLIFY_NATIVE_NPM_PACKAGES is 1', () => {
        setFlag(undefined);
        expect(isNativePackagesEnabled()).toBe(false);
        setFlag('true');
        expect(isNativePackagesEnabled()).toBe(false);
        setFlag('0');
        expect(isNativePackagesEnabled()).toBe(false);
        setFlag('1');
        expect(isNativePackagesEnabled()).toBe(true);
    });
});
describe('mint dev with native npm packages off', () => {
    beforeEach(() => setFlag(undefined));
    it('skips the packages runtime and tells prebuild to ignore packages', async () => {
        await dev(argv);
        expect(processExitMock).not.toHaveBeenCalled();
        expect(startPackagesDev).not.toHaveBeenCalled();
        expect(prebuild).toHaveBeenCalledWith(expect.any(String), expect.objectContaining({ nativePackages: false }));
    });
    it('lets /_mintlify/pkg requests fall through to the next handler', async () => {
        configurePreviewPath(3000);
        await startRun();
        expect(await get('/_mintlify/pkg/x/client/a.js')).toBe('next');
        expect(packageRoute.handler).not.toHaveBeenCalled();
        expect(setPackagesRebuiltListener).not.toHaveBeenCalled();
        expect(listener).toHaveBeenCalledWith(expect.any(Function), expect.objectContaining({ nativePackages: false }), expect.any(Promise));
    });
});
describe('mint dev with MINTLIFY_NATIVE_NPM_PACKAGES=1', () => {
    beforeEach(() => setFlag('1'));
    it('starts the packages runtime and tells prebuild to read packages', async () => {
        await dev(argv);
        expect(processExitMock).not.toHaveBeenCalled();
        expect(startPackagesDev).toHaveBeenCalledOnce();
        expect(prebuild).toHaveBeenCalledWith(expect.any(String), expect.objectContaining({ nativePackages: true }));
    });
    it('serves /_mintlify/pkg from the package route', async () => {
        configurePreviewPath(3000);
        await startRun();
        expect(await get('/_mintlify/pkg/x/client/a.js')).toBe('pkg');
        expect(setPackagesRebuiltListener).toHaveBeenCalledWith(expect.any(Function));
        expect(listener).toHaveBeenCalledWith(expect.any(Function), expect.objectContaining({ nativePackages: true }), expect.any(Promise));
    });
});
